      if (num >= 3) return 5 - get.value(card);
      if (num >= 2 && player.isDamaged() && ui.selected.cards.length < 1) return 7 - get.value(card);
      if (num >= 1 && player.isDamaged() && !ui.selected.cards.length) return 6 - get.value(card);
      return 0;
