  lg_zhijing: {
    audio: 'ext:千秋霸业/Sound:2',
    group: 'lg_zhijing_gain',
    subSkill: {
      gain: {
        usable: 2,
        trigger: {
          player: ['damageEnd', 'recoverEnd'],
        },
        filter(event, player, name) {
          if (name == 'damageEnd' && !event.nature) return false;
          return event.num > 0 && player.isDamaged();
        },
        content() {
          'step 0';
          event.count = Math.min(trigger.num, 9);
          event.num = player.getDamagedHp();
          ('step 1');
          var cards = get.cards(event.num);
          game.cardsGotoOrdering(cards);
          player.showCards(cards, '止境');
          var suits = [];
          for (var i = 0; i < cards.length; i++) {
            suits.add(cards[i].suit);
          }
          event.suits = suits;
          event.countx = 0;
          ('step 2');
          player
            .chooseTarget('止境:选择一名角色')
            .set('filterTarget', function (card, player, target) {
              return target.countCards('hej') > 0;
            })
            .set('ai', function (target) {
              var att = get.attitude(player, target);
              if (att > 1 && target.countCards('j') > 0) return 10 * att;
              return -att * target.countCards('he');
            });
          ('step 3');
          if (result.bool && result.targets.length) {
            var target = result.targets[0];
            event.target = target;
            player
              .choosePlayerCard(
                'hej',
                '弃置' + get.translation(target) + '区域内的一张牌' + (event.suits.length ? ';或将场上的一张' + get.translation(event.suits) + '牌移动' : ''),
                true,
                function (button) {
                  var player = _status.event.player;
                  var card = button.link;
                  var target = _status.event.parent.target;
                  if (get.attitude(player, target) > 0) {
                    if (get.position(card) == 'j') return 4;
                    if (get.value(card, target) <= 0) return -get.effect(target, card, target, player);
                  } else {
                    if (get.position(card) == 'e' && !target.hasSkillTag('noe')) {
                      var max = game.countPlayer(function (current) {
                        if (get.effect(current, card, current, player) > 1 && get.effect(target, card, target, player) < 0) return get.value(card, target);
                        return 0;
                      });
                      if (max > 0) return get.value(card, target) + max;
                      return get.value(card, target);
                    } else if (get.position(card) == 'j') {
                      return -1;
                    } else {
                      return get.buttonValue(button);
                    }
                  }
                  return -1;
                },
                target
              )
              .set('filterButton', function (button) {
                return true;
              });
          } else {
            event.goto(7);
          }
          ('step 4');
          if (result.bool) {
            var card = result.cards[0];
            event.card = card;
            if (get.position(card) == 'j' && event.suits.includes(card.suit)) {
              player
                .chooseTarget(1, '将' + get.translation(card) + '移至另一名角色的判定区？', function (card, player, target) {
                  return target.canAddJudge(_status.event.card);
                })
                .set('ai', function (target) {
                  return get.effect(target, _status.event.card, player, player);
                })
                .set('card', card);
            } else if (get.position(card) == 'e' && event.suits.includes(card.suit)) {
              player
                .chooseTarget(1, '将' + get.translation(card) + '移至另一名角色的装备区？', function (card, player, target) {
                  return target.canEquip(_status.event.card);
                })
                .set('ai', function (target) {
                  return get.effect(target, _status.event.card, player, player);
                })
                .set('card', card);
            } else {
              event.directresult = true;
            }
          } else {
            event.finish();
          }
          ('step 5');
          if (result.targets && !event.directresult) {
            var target2 = result.targets[0];
            target.$give(card, target2);
            event.suits.remove(card.suit);
            if (get.position(card) == 'e') {
              target2.equip(card);
            } else {
              target2.addJudge(card);
            }
          } else {
            event.countx++;
            target.discard(card, target == player ? 'notBySelf' : null);
            delete event.directresult;
          }
          ('step 6');
          if (event.suits.length - event.countx > 0) {
            event.goto(2);
          }
          ('step 7');
          event.count--;
          if (event.count > 0) {
            player.chooseBool('重复此流程？').set('choice', true);
          } else {
            event.finish();
          }
          ('step 8');
          if (result.bool) {
            event.goto(1);
          }
        },
      },
    },
    action_tag: {
      overall: 4,
      draw: 1.5,
      discard: 1,
      loseHp_defend: 2,
    },
    usable: 1,
    trigger: {
      target: 'useCardToTarget',
    },
    filter(event, player) {
      if (player == event.player) return false;
      if (player.hp < event.player.hp) return false;
      if (player.hp < 1) return false;
      var card = event.card;
      if (get.type(card, 'trick') != 'equip') return true;
      return false;
    },
    prompt(event, player) {
      return '回复1点体力,令其使用的【' + get.translation(event.card) + '】对你无效？';
    },
    check(event, player) {
      if (event.parent.excluded.includes(player)) return false;
      if (get.effect(player, event.card, event.player, player) >= 0) return false;
      if (get.tag(event.card, 'respondSha')) {
        if (
          player.countCards('h', {
            name: 'sha',
          }) == 0
        ) {
          return true;
        }
      } else if (get.tag(event.card, 'respondShan')) {
        if (
          player.countCards('h', {
            name: 'shan',
          }) == 0
        ) {
          return true;
        }
      } else if (get.tag(event.card, 'damage')) {
        if (player.countCards('h') < 2) return true;
      }
      return false;
    },
    content() {
      'step 0';
      var num = player.getDamagedHp();
      player.recover();
      player.draw(num);
      ('step 1');
      if (!event.isMine()) game.delayx();
      trigger.parent.targets.remove(player);
      trigger.parent.triggeredTargets2.remove(player);
      ('step 2');
    },
    ai: {
      threaten: 0.8,
    },
  },
