      ('step 4');
      player.chooseTarget('秘宝:选择一名其他角色', true, function (card, player, target) {
        return target != player;
      }).ai = function (target) {
        return get.attitude(player, target) > 2;
      };
      ('step 5');
      if (result.bool) {
        player.line(result.targets[0]);
        game.log(player, '将', event.list, '交给了', result.targets[0]);
        result.targets[0].gain(event.list, 'gain2');
        player.removeSkill('lg_mibao');
        player.gain(game.createCard('lg_shanyaoshike'), 'gain2');
        if (player.isDamaged()) player.recover();
      }
