  lg_fengshen: {
    audio: 'ext:千秋霸业/Sound:2',
    trigger: {
      player: 'useCardEnd',
    },
    forced: true,
    mark: true,
    marktext: '封',
    intro: {
      name: '封神',
      content(storage, player) {
        var str = '';
        var num1 = player.countMark('lg_fengshen_from');
        var num2 = player.countMark('lg_fengshen_to');
        var num3 = player.countMark('lg_fengshen_att');
        if (num1) str += '进攻距离:' + get.translation(num1) + '<br>';
        if (num2) str += '防御距离:' + get.translation(num2) + '<br>';
        if (num3) str += '攻击范围:' + get.translation(num3);
        return str;
      },
    },
    filter(event, player) {
      if (get.type(event.card) != 'equip') return false;
      if (!event.cards || event.cards.length != 1) return false;
      var subtype = get.subtype(event.card);
      if (player.isDisabled(subtype)) return false;
      return player.getCards('e').includes(event.cards[0]);
    },
    content() {
      'step 0';
      event.card = trigger.cards[0];
      if (get.subtype(event.card) == 'equip3' || get.subtype(event.card) == 'equip4') {
        event.goto(1);
      } else {
        var skills = get.info(event.card).skills;
        if (!skills) return;
        skills = skills.slice(0);
        for (var j of skills) {
          player.addSkillLog(j);
        }
      }
      ('step 1');
      var num1 = 0; //进攻
      var num2 = 0; //防御
      var num3 = 0; //攻击
      var info = get.info(event.card).distance;
      if (!info) return;
      if (info.globalFrom) {
        num1 += -info.globalFrom;
        player.addSkill('lg_fengshen_from');
        player.addMark('lg_fengshen_from', num1, false);
      }
      if (info.globalTo) {
        num2 += info.globalTo;
        player.addSkill('lg_fengshen_to');
        player.addMark('lg_fengshen_to', num2, false);
      }
      if (info.attackFrom) {
        num3 += -info.attackFrom;
        player.addSkill('lg_fengshen_att');
        //player.draw(num3);
        player.addMark('lg_fengshen_att', num3, false);
      }
      ('step 2');
      var e = get.subtype(event.card);
      player.disableEquip(e);
      ('step 3');
      player
        .chooseTarget('将' + get.translation(event.card) + '交给一名其他角色？', function (card, player, target) {
          return target != player;
        })
        .set('ai', function (target) {
          var att = get.attitude(player, target);
          if (att <= 0) return -1;
          if (target.canUse(event.card, target)) {
            var eff = get.effect(target, event.card, player, player);
            if (eff > 0) {
              if (!target.isEmpty(get.subtype(event.card))) eff = eff / 3;
            }
            if (eff > 0) return eff;
          }
          return 1;
        });
      ('step 4');
      if (result.bool) {
        player.give(event.card, result.targets[0], true);
        player.draw(3);
        //result.targets[0].gain(event.card,"give",player);
      }
    },
    ai: {
      expose: 0.3,
      threaten: 1.2,
    },
    subSkill: {
      from: {
        mod: {
          globalFrom(from, to, distance) {
            return distance - from.countMark('lg_fengshen_from');
          },
        },
      },
      to: {
        mod: {
          globalTo(from, to, distance) {
            return distance + to.countMark('lg_fengshen_to');
          },
        },
      },
      att: {
        mod: {
          attackRange(from, distance) {
            return distance + from.countMark('lg_fengshen_att');
          },
        },
      },
    },
  },
