            if (player.hasSkill('qinglonglingzhu')) {
              if (rand2) return name == 'chiyuxi' ? 0.8 : 0;
              return name == 'jingleishan' ? 0.8 : 0;
            }
            if (rand2) return name == 'wanjian' ? 0.8 : 0;
            return name == 'nanman' ? 0.8 : 0;
