            if ((event.filterCard && event.filterCard({ name: 'wuxie' }, player, event)) || event.filterCard({ name: 'shan' }, player, event)) {
              return 4;
            }
            if (event.filterCard && event.filterCard({ name: 'sha' }, player, event)) {
              return 2.9;
            }
