      ('step 3');
      var _wuxie = event._wuxie_evtt;
      var _useCard = event._wuxie_evt;
      var func = _wuxie.settle;
      _wuxie.settle = function () {
        func();
        var that = this;
        if (!that.state) {
          _useCard.excluded.addArray(event.targetsx);
        }
      };
