  lg_suli: {
    audio: 'ext:千秋霸业/Centuries:2',
    group: 'lg_suli1',
    trigger: {
      player: 'phaseZhunbeiBegin',
    },
    forced: true,
    _priority: 12121,
    content() {
      'step 0';
      event.videoId = lib.status.videoId++;
      var func = function (id, bool) {
        var list = ['摸牌阶段', '出牌阶段', '弃牌阶段'];
        var choiceList = ui.create.dialog('发动此技能？', 'forcebutton');
        choiceList.videoId = id;
        for (var i = 0; i < list.length; i++) {
          var str = '<div class="popup text" style="width:calc(100% - 10px);display:inline-block">';
          if (i == 0 && !bool) str += '<div style="opacity:0.5">';
          str += list[i];
          if (i == 0 && !bool) str += '</div>';
          str += '</div>';
          var next = choiceList.add(str);
          next.firstChild.addEventListener(lib.config.touchscreen ? 'touchend' : 'click', ui.click.button);
          next.firstChild.link = i;
          Object.setPrototypeOf(next, lib.element.Button.prototype); //QQQ
          choiceList.buttons.add(next.firstChild);
        }
        return choiceList;
      };
      if (player.isOnline2()) {
        player.send(func, event.videoId, true);
      }
      event.dialog = func(event.videoId, true);
      if (player != game.me || _status.auto) {
        event.dialog.style.display = 'none';
      }
      var next = player.chooseButton();
      next.set('dialog', event.videoId);
      next.set('forced', false);
      next.set('selectButton', [1, 2]);
      next.set('ai', function (button) {
        var player = _status.event.player;
        var m = 0;
        var n = 0;
        var y = 0;
        var x = 0;
        var num = 0;
        game.countPlayer(function (current) {
          if (current != player && get.attitude(player, current) > 0) {
            if (current.countCards('h') + 2 < current.getHandcardLimit()) m++;
            if (current.countCards('h') > 1) y++;
            num++;
          }
        });
        switch (button.link) {
          case 0: {
            if (m == 0) return -1;
            if (!player.countCards('h') || player.hp <= 1) return -1;
            if (player.countCards('j', 'lebu')) return -1;
            if (player.countCards('j', 'caomu') || player.countCards('j', 'bingliang')) return 2;
            return player.countCards('h') - 2;
          }
          case 1: {
            if (y == 0) return -1;
            if (player.countCards('j', 'lebu')) return 5;
            if (player.countCards('j', 'caomu') || player.countCards('j', 'bingliang')) x = 2;
            return 5 - player.countCards('h') - x;
          }
          case 2: {
            if (num == 0) return 10;
            if (player.countCards('h') - 2 > 0 && m != 0) n += 1.5;
            if (player.countCards('j', 'caomu') || player.countCards('j', 'bingliang')) n -= 1.5;
            if (player.countCards('j', 'lebu')) return 5;
            return player.countCards('h') - player.getHandcardLimit() + n;
          }
        }
      });
      ('step 1');
      if (player.isOnline2()) {
        player.send('closeDialog', event.videoId);
      }
      event.dialog.close();
      ('step 2');
      if (result.links?.length) {
        if (player.isOnline2()) {
          player.send('closeDialog', event.videoId);
        }
        var map = [
          function (player, target) {
            player.addTempSkill('lg_suli_draw');
            player.skip('phaseDraw');
          },
          function (player, target) {
            player.addTempSkill('lg_suli_use');
            player.skip('phaseUse');
          },
          function (player, target) {
            player.addTempSkill('lg_suli_discard');
            player.skip('phaseDiscard');
          },
        ];

        for (var i of result.links) {
          map[i](player);
        }
      } else event.finish();
      ('step 3');
      player
        .chooseTarget(get.prompt('lg_suli'), '请选择一名其他角色', function (card, player, target) {
          return target != player;
        })
        .set('ai', function (target) {
          var player = _status.event.player;
          var att = get.attitude(player, target);
          var dn = target.countCards('h') - target.getHandcardLimit();
          var n = target.countCards('h');
          if (player.hasSkill('lg_suli_discard')) {
            if (!player.hasSkill('lg_suli_use') && !player.hasSkill('lg_suli_draw') && att < 0) return dn;
            if (player.hasSkill('lg_suli_use')) {
              if (dn <= 2) return att;
            }
            if (player.hasSkill('lg_suli_draw')) {
              if (att > 0) return -dn + 0.5;
              if (att <= 0) return dn - 0.5;
            }
          }
          if (player.hasSkill('lg_suli_draw') && !player.hasSkill('lg_suli_use') && !player.hasSkill('lg_suli_discard') && att > 0) return Infinity - n;
          if (!player.hasSkill('lg_suli_draw') && player.hasSkill('lg_suli_use') && !player.hasSkill('lg_suli_discard') && att > 0) return n;
          if (player.hasSkill('lg_suli_draw') && player.hasSkill('lg_suli_use')) return att + n;
          return 0;
        });
      ('step 4');
      if (result.bool) {
        if (player.hasSkill('lg_suli_draw')) result.targets[0].addTempSkill('lg_suli_draw');
        if (player.hasSkill('lg_suli_use')) result.targets[0].addTempSkill('lg_suli_use');
        if (player.hasSkill('lg_suli_discard')) result.targets[0].addTempSkill('lg_suli_discard');
      }
    },
  },
