          var currentcard = ui.discardPile.childNodes[i];
          currentcard.vanishtag.length = 0;
          if (get.info(currentcard).vanish || currentcard.storage.vanish) {
            currentcard.remove();
            continue;
          }
          cards.push(currentcard);
